function escapeGermanRegexPart(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

const germanWordPatterns = germanWordReplacements.map(([from, to]) => [new RegExp(`\\b${escapeGermanRegexPart(from)}\\b`, 'gi'), to] as const);

function translateGermanCatalog(messages: Messages): Messages {
  const result: Messages = {};
  for (const [key, original] of Object.entries(messages)) {
    if (germanKeyFixes[key]) {
      result[key] = germanKeyFixes[key];
      continue;
    }
    let value = germanExactPhrases[original] ?? original;
    for (const [pattern, replacement] of germanWordPatterns) {
      value = value.split(/(\{[^}]+\})/g).map((part) => part.startsWith('{') ? part : part.replace(pattern, replacement)).join('');
    }
    result[key] = value;
  }
  return result;
}

const catalogs: Record<AppLocale, Messages> = {
  en: { ...en, ...localeOverrides.en },
  es: { ...es, ...localeOverrides.es },
  pt: { ...pt, ...translatedPt, ...localeOverrides.pt },
  fr: { ...fr, ...translatedFr, ...localeOverrides.fr },
  de: { ...de, ...translateGermanCatalog(translatedDe), ...localeOverrides.de },
};

const COUNTRY_LOCALE: Record<string, AppLocale> = {
  ES: 'es', MX: 'es', AR: 'es', CO: 'es', CL: 'es', PE: 'es', VE: 'es', EC: 'es', GT: 'es', CU: 'es',
  BO: 'es', DO: 'es', HN: 'es', PY: 'es', SV: 'es', NI: 'es', CR: 'es', PA: 'es', UY: 'es', GQ: 'es',
  PR: 'es', US: 'en', GB: 'en', AU: 'en', NZ: 'en', IE: 'en', SG: 'en', ZA: 'en', IN: 'en', PH: 'en',
  NG: 'en', KE: 'en', GH: 'en', JM: 'en', TT: 'en', CA: 'en', BR: 'pt', PT: 'pt', AO: 'pt', MZ: 'pt',
  CV: 'pt', GW: 'pt', ST: 'pt', TL: 'pt', FR: 'fr', BE: 'fr', LU: 'fr', MC: 'fr', SN: 'fr', CI: 'fr',
  CM: 'fr', MG: 'fr', HT: 'fr', CD: 'fr', CG: 'fr', GA: 'fr', BJ: 'fr', NE: 'fr', ML: 'fr', BF: 'fr',
  TG: 'fr', DE: 'de', AT: 'de', LI: 'de', CH: 'de',
};

let activeLocale: AppLocale = 'en';
let signals: LocaleSignals = {
  deviceTag: 'en',
  deviceLocale: 'en',
  ipCountry: null,
  ipCountryName: null,
  ipLocale: null,
};

export function isAppLocale(value: unknown): value is AppLocale {
  return typeof value === 'string' && (APP_LOCALES as readonly string[]).includes(value);
}

export function isLanguagePreference(value: unknown): value is LanguagePreference {
  return value === 'auto' || isAppLocale(value);
}

export function currentLocale(): AppLocale {
  return activeLocale;
}

export function localeSignals(): LocaleSignals {
  return signals;
}

export function localeLabel(locale: AppLocale, inLocale: AppLocale = locale): string {
  return catalogs[inLocale][`lang.${locale}`] ?? catalogs.en[`lang.${locale}`] ?? locale;
}

export function t(key: string, vars: Record<string, string | number> = {}): string {
  const template = catalogs[activeLocale][key] ?? catalogs.en[key] ?? key;
  return template.replace(/\{(\w+)\}/g, (_, name: string) => String(vars[name] ?? ''));
}

export function applyDomI18n(root: ParentNode = document): void {
  root.querySelectorAll<HTMLElement>('[data-i18n]').forEach((node) => {
    const key = node.dataset.i18n;
    if (key) node.textContent = t(key);
  });
  root.querySelectorAll<HTMLElement>('[data-i18n-title]').forEach((node) => {
    const key = node.dataset.i18nTitle;
    if (key) node.title = t(key);
  });
  root.querySelectorAll<HTMLElement>('[data-i18n-placeholder]').forEach((node) => {
    const key = node.dataset.i18nPlaceholder;
    if (key && 'placeholder' in node) (node as HTMLInputElement).placeholder = t(key);
  });
  root.querySelectorAll<HTMLElement>('[data-i18n-aria]').forEach((node) => {
    const key = node.dataset.i18nAria;
    if (key) node.setAttribute('aria-label', t(key));
  });
  document.documentElement.lang = activeLocale;
}

export function readDeviceLocale(): { tag: string; locale: AppLocale | null } {
  const intlLocale = (() => {
    try {
      return Intl.DateTimeFormat().resolvedOptions().locale;
    } catch {
      return '';
    }
  })();
  const tags = [...(navigator.languages ?? []), navigator.language, intlLocale, document.documentElement.lang]
    .filter((value): value is string => typeof value === 'string' && value.trim().length > 0)
    .filter((value, index, list) => list.indexOf(value) === index);
  const firstTag = tags[0] ?? 'en';
  for (const item of tags) {
    const locale = localeFromTag(item);
    if (locale) return { tag: item, locale };
  }
  return { tag: firstTag, locale: null };
}

export function localeFromTag(tag: string): AppLocale | null {
  const lower = tag.trim().toLowerCase().replace(/_/g, '-');
  const primary = lower.split('-')[0] ?? '';
  if (primary === 'es') return 'es';
  if (primary === 'pt') return 'pt';
  if (primary === 'fr') return 'fr';
  if (primary === 'de') return 'de';
  if (primary === 'en') return 'en';
  return null;
}

export function localeFromCountry(code: string | null | undefined): AppLocale | null {
  if (!code) return null;
  return COUNTRY_LOCALE[code.trim().toUpperCase()] ?? null;
}

export function resolveLocale(preference: LanguagePreference, next: LocaleSignals): AppLocale {
  if (preference !== 'auto') return preference;
  const device = next.deviceLocale;
  const ip = next.ipLocale;
  // Windows/WebView often reports en-US even when the user is abroad.
  // Prefer a non-English IP locale over a generic English device locale.
  if (device && ip) {
    if (device === ip) return device;
    if (device === 'en' && ip !== 'en') return ip;
    return device;
  }
  return ip ?? device ?? 'en';
}

export function setActiveLocale(locale: AppLocale): boolean {
  const changed = activeLocale !== locale;
  activeLocale = locale;
  return changed;
}

export function setLocaleSignals(next: Partial<LocaleSignals>): void {
  signals = { ...signals, ...next };
}

const IP_CACHE_KEY = 'comesade.ip-locale';
const LOCALE_API_URL = 'https://comesade-api.kingfrianfrian16.workers.dev/v1/locale';

type IpCache = { at: number; country: string; countryName: string; locale: AppLocale | null };

export async function detectIpLocale(): Promise<{ country: string | null; countryName: string | null; locale: AppLocale | null }> {
  try {
    const cached = readIpCache();
    if (cached) return { country: cached.country, countryName: cached.countryName, locale: cached.locale };

    const fromNative = await detectIpLocaleNative();
    if (fromNative.country) {
      writeIpCache({
        at: Date.now(),
        country: fromNative.country,
        countryName: fromNative.countryName ?? fromNative.country,
        locale: fromNative.locale,
      });
      return fromNative;
    }

    const fromWorker = await detectIpLocaleWorker();
    if (fromWorker.country) {
      writeIpCache({
        at: Date.now(),
        country: fromWorker.country,
        countryName: fromWorker.countryName ?? fromWorker.country,
        locale: fromWorker.locale,
      });
      return fromWorker;
    }

    const fromCloudflare = await detectIpLocaleCloudflare();
    if (fromCloudflare.country) {
      writeIpCache({
        at: Date.now(),
        country: fromCloudflare.country,
        countryName: fromCloudflare.countryName ?? fromCloudflare.country,
        locale: fromCloudflare.locale,
      });
      return fromCloudflare;
    }

    const fromIpwho = await detectIpLocaleIpwho();
    if (fromIpwho.country) {
      writeIpCache({
        at: Date.now(),
        country: fromIpwho.country,
        countryName: fromIpwho.countryName ?? fromIpwho.country,
        locale: fromIpwho.locale,
      });
      return fromIpwho;
    }

    const fromIpapi = await detectIpLocaleIpapi();
    if (fromIpapi.country) {
      writeIpCache({
        at: Date.now(),
        country: fromIpapi.country,
        countryName: fromIpapi.countryName ?? fromIpapi.country,
        locale: fromIpapi.locale,
      });
      return fromIpapi;
    }

    return { country: null, countryName: null, locale: null };
  } catch {
    return { country: null, countryName: null, locale: null };
  }
}

async function detectIpLocaleWorker(): Promise<{ country: string | null; countryName: string | null; locale: AppLocale | null }> {
  try {
    const controller = new AbortController();
    const timer = window.setTimeout(() => controller.abort(), 3500);
    try {
      const response = await fetch(LOCALE_API_URL, {
        cache: 'no-store',
        signal: controller.signal,
      });
      if (!response.ok) return { country: null, countryName: null, locale: null };
      const data = await response.json() as { country?: string; countryName?: string };
      const country = typeof data.country === 'string' ? data.country.trim().toUpperCase() : '';
      if (!/^[A-Z]{2}$/.test(country) || country === 'XX' || country === 'T1') {
        return { country: null, countryName: null, locale: null };
      }
      const countryName = typeof data.countryName === 'string' && data.countryName.trim()
        ? data.countryName.trim()
        : country;
      return { country, countryName, locale: localeFromCountry(country) };
    } finally {
      window.clearTimeout(timer);
    }
  } catch {
    return { country: null, countryName: null, locale: null };
  }
}

async function detectIpLocaleNative(): Promise<{ country: string | null; countryName: string | null; locale: AppLocale | null }> {
  try {
    const result = await invoke<{ country?: string | null; countryName?: string | null }>('detect_ip_country');
    const country = typeof result?.country === 'string' ? result.country.trim().toUpperCase() : '';
    if (!country || country.length !== 2) return { country: null, countryName: null, locale: null };
    const countryName = typeof result?.countryName === 'string' && result.countryName.trim()
      ? result.countryName.trim()
      : country;
    return { country, countryName, locale: localeFromCountry(country) };
  } catch {
    return { country: null, countryName: null, locale: null };
  }
}

async function detectIpLocaleCloudflare(): Promise<{ country: string | null; countryName: string | null; locale: AppLocale | null }> {
  try {
    const controller = new AbortController();
    const timer = window.setTimeout(() => controller.abort(), 4500);
    const response = await fetch('https://www.cloudflare.com/cdn-cgi/trace', {
      cache: 'no-store',
      signal: controller.signal,
    });
    window.clearTimeout(timer);
    if (!response.ok) return { country: null, countryName: null, locale: null };
    const text = await response.text();
    const match = text.match(/(?:^|\n)loc=([A-Za-z]{2})(?:\n|$)/);
    const country = match?.[1]?.toUpperCase() ?? '';
    if (!country || country === 'XX' || country === 'T1') return { country: null, countryName: null, locale: null };
    return { country, countryName: country, locale: localeFromCountry(country) };
  } catch {
    return { country: null, countryName: null, locale: null };
  }
}

async function detectIpLocaleIpwho(): Promise<{ country: string | null; countryName: string | null; locale: AppLocale | null }> {
  try {
    const controller = new AbortController();
    const timer = window.setTimeout(() => controller.abort(), 4500);
    const response = await fetch('https://ipwho.is/', { cache: 'no-store', signal: controller.signal });
    window.clearTimeout(timer);
    if (!response.ok) return { country: null, countryName: null, locale: null };
    const data = await response.json() as { success?: boolean; country_code?: string; country?: string };
    if (data.success === false) return { country: null, countryName: null, locale: null };
    const country = typeof data.country_code === 'string' ? data.country_code.toUpperCase() : '';
    const countryName = typeof data.country === 'string' ? data.country : country;
    if (!country) return { country: null, countryName: null, locale: null };
    return { country, countryName: countryName || null, locale: localeFromCountry(country) };
  } catch {
    return { country: null, countryName: null, locale: null };
  }
}

async function detectIpLocaleIpapi(): Promise<{ country: string | null; countryName: string | null; locale: AppLocale | null }> {
  try {
    const controller = new AbortController();
    const timer = window.setTimeout(() => controller.abort(), 4500);
    const response = await fetch('https://ipapi.co/json/', { cache: 'no-store', signal: controller.signal });
    window.clearTimeout(timer);
    if (!response.ok) return { country: null, countryName: null, locale: null };
    const data = await response.json() as { country_code?: string; country_name?: string; error?: boolean };
    if (data.error) return { country: null, countryName: null, locale: null };
    const country = typeof data.country_code === 'string' ? data.country_code.toUpperCase() : '';
    const countryName = typeof data.country_name === 'string' ? data.country_name : country;
    if (!country) return { country: null, countryName: null, locale: null };
    return { country, countryName: countryName || null, locale: localeFromCountry(country) };
  } catch {
    return { country: null, countryName: null, locale: null };
  }
}

function readIpCache(): IpCache | null {
  try {
    const raw = sessionStorage.getItem(IP_CACHE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as Partial<IpCache>;
    if (typeof parsed.at !== 'number' || Date.now() - parsed.at > 6 * 60 * 60 * 1000) return null;
    if (typeof parsed.country !== 'string') return null;
    return {
      at: parsed.at,
      country: parsed.country,
      countryName: typeof parsed.countryName === 'string' ? parsed.countryName : parsed.country,
      locale: isAppLocale(parsed.locale) ? parsed.locale : localeFromCountry(parsed.country),
    };
  } catch {
    return null;
  }
}

function writeIpCache(value: IpCache): void {
  try {
    sessionStorage.setItem(IP_CACHE_KEY, JSON.stringify(value));
  } catch {
    // ignore quota
  }
}
